    c = rem % S0
    rem = rem // S0
    po = c * T0
    c = rem % S1
    rem = rem // S1
    po += c * T1
    c = rem % S2
    rem = rem // S2
    po += c * T2
    c = rem % S3
    rem = rem // S3
    po += c * T3
    c = rem % S4
    rem = rem // S4
    po += c * T4
    c = rem % S5
    rem = rem // S5
    po += c * T5
    c = rem % S6
    rem = rem // S6
    po += c * T6
