def _coalesce(shape, stride):
    """TensorIterator-style dim coalescing, innermost (smallest stride) first."""
    dims = [(int(sz), int(st)) for sz, st in zip(shape, stride) if int(sz) != 1]
    if not dims:
        return [(1, 0)]
    dims = sorted(dims, key=lambda d: d[1])
    out = []
    cur_size, cur_stride = dims[0]
    for sz, st in dims[1:]:
        if st == cur_stride * cur_size:
            cur_size *= sz
        else:
            out.append((cur_size, cur_stride))
            cur_size, cur_stride = sz, st
    out.append((cur_size, cur_stride))
    return out


def _block_for(itemsize):
    elems = 65536 // itemsize
    if elems < 256:
        elems = 256
    elif elems > 32768:
        elems = 32768
    return elems


# Per-signature cached CompiledKernel runners. Building a launch through the JIT
# entry point re-binds arguments and recomputes a specialization key on every call,
# which dominates a call whose whole payload is a few KiB; the compiled runner goes
# straight to the launcher. Keyed by everything that affects the compiled binary.
_RUNNERS = {}
_NATIVE = object()


def _make_runner(args, grid3):
    try:
        ker = _fdiv_flat4.warmup(*args, grid=grid3, num_stages=1, num_warps=1)
        if hasattr(ker, "result"):
            ker = ker.result()
        return ker[grid3]
    except Exception:
        return _NATIVE


def _launch_flat(group, sval, sp, is_ptr):
    for start in range(0, len(group), 4):
        chunk = group[start : start + 4]
        block = _block_for(chunk[0][0].element_size())
        xs = [c[0] for c in chunk]
        ns = [c[1] for c in chunk]
        while len(xs) < 4:
            xs.append(xs[-1])
            ns.append(0)
        k1 = -(-ns[0] // block)
        k2 = k1 + (-(-ns[1] // block))
        k3 = k2 + (-(-ns[2] // block))
        grid = k3 + (-(-ns[3] // block))
        args = (
            xs[0],
            xs[1],
            xs[2],
            xs[3],
            sval,
            sp,
            ns[0],
            ns[1],
            ns[2],
            ns[3],
            k1,
            k2,
            k3,
            block,
            is_ptr,
        )
        key = (chunk[0][0].dtype, ns[0], ns[1], ns[2], ns[3], block, is_ptr)
        runner = _RUNNERS.get(key)
        if runner is None:
            runner = _make_runner(args, (grid, 1, 1))
            _RUNNERS[key] = runner
        if runner is _NATIVE:
            _fdiv_flat4[(grid,)](*args, num_stages=1, num_warps=1)
        else:
            runner(*args)


def foreach_div_scalar_(self, scalar):
    if torch.is_tensor(self):
        seq = (self,)
    elif isinstance(self, (list, tuple)):
        seq = self
    else:
        seq = (self,)
    n = len(seq)
    if n == 0:
        return None

    is_ptr = torch.is_tensor(scalar)
    if is_ptr:
        sp = scalar
        sval = 0.0
    else:
        sp = seq[0]
        sval = float(scalar)

    if n == 4:
        # Flat hot path: four contiguous tensors of one dtype and one numel.
        a = seq[0]
        b = seq[1]
        c = seq[2]
        d = seq[3]
        if (
            type(a) is torch.Tensor
            and type(b) is torch.Tensor
            and type(c) is torch.Tensor
            and type(d) is torch.Tensor
        ):
            dt = a.dtype
            ne = a.numel()
            if (
                ne != 0
                and a.is_contiguous()
                and b.is_contiguous()
                and c.is_contiguous()
                and d.is_contiguous()
                and b.dtype is dt
                and c.dtype is dt
                and d.dtype is dt
                and b.numel() == ne
                and c.numel() == ne
                and d.numel() == ne
            ):
                pa = a.data_ptr()
                pb = b.data_ptr()
                pc = c.data_ptr()
                pd = d.data_ptr()
                if (
                    pa != pb
                    and pa != pc
                    and pa != pd
                    and pb != pc
                    and pb != pd
                    and pc != pd
                ):
                    block = _block_for(a.element_size())
                    bpt = -(-ne // block)
                    key = (dt, ne, block, is_ptr)
                    runner = _RUNNERS.get(key)
                    args = (
                        a,
                        b,
                        c,
                        d,
                        sval,
                        sp,
                        ne,
                        ne,
                        ne,
                        ne,
                        bpt,
                        bpt * 2,
                        bpt * 3,
                        block,
                        is_ptr,
                    )
                    if runner is None:
                        runner = _make_runner(args, (bpt * 4, 1, 1))
                        _RUNNERS[key] = runner
                    if runner is _NATIVE:
                        _fdiv_flat4[(bpt * 4,)](*args, num_stages=1, num_warps=1)
                    else:
                        runner(*args)
                    return None

    live = []
    for t in seq:
        if torch.is_tensor(t) and t.numel() != 0:
            live.append(t)
    if not live:
        return None

    if len(live) > 1 and len({t.data_ptr() for t in live}) != len(live):
        # Entries sharing storage must be divided sequentially, as torch does.
        for t in live:
            _launch_flat([(t, t.numel())], sval, sp, is_ptr)
        return None

    groups = {}
    strided = []
    for t in live:
        if t.is_contiguous():
            dtype = t.dtype
            g = groups.get(dtype)
            if g is None:
                groups[dtype] = [(t, t.numel())]
            else:
                g.append((t, t.numel()))
        else:
            strided.append((t, t.numel()))

    for g in groups.values():
        _launch_flat(g, sval, sp, is_ptr)

    for t, numel in strided:
        dims = _coalesce(t.shape, t.stride())
        block = _block_for(t.element_size())
        if len(dims) == 1 and (dims[0][1] == 1 or numel == 1):
            _launch_flat([(t, numel)], sval, sp, is_ptr)
            continue
        if len(dims) > _NDIMS:
            raise RuntimeError(
                "foreach_div_scalar_: coalesced rank above %d is unsupported" % _NDIMS
            )
        dims = dims + [(1, 0)] * (_NDIMS - len(dims))
        _fdiv_nd[(triton.cdiv(numel, block),)](
            t,
            sval,
            sp,
            numel,
            dims[0][0],
            dims[1][0],
            dims[2][0],
            dims[3][0],
            dims[4][0],
            dims[5][0],
            dims[6][0],
            dims[7][0],
            dims[0][1],
            dims[1][1],
            dims[2][1],
            dims[3][1],
            dims[4][1],
            dims[5][1],
            dims[6][1],
            dims[7][1],
            block,
            is_ptr,
            num_stages=1,
            num_warps=1,
        )
    return None
